def _responder_chat_mensagem(*, trilha_dir: Path, environ, metodo: str):
    """`POST /api/chat/mensagem`: registra uma pergunta ou resposta do fluxo guiado na trilha, pelas
    MESMAS funções que `interfaces.cli` já usa (issue #51, parte 2 — dono único da escrita da
    trilha, LEI 11). Nunca chama `gerar_paineis` (mesmo padrão mais leve de `_responder_chat_contato`
    — só cotar/contratar regeneram o painel a cada chamada)."""
    if metodo != "POST":
        return _json(*_METODO_NAO_SUPORTADO)
    dados = _ler_corpo_json(environ)
    if dados is None:
        return _json("400 Bad Request", {"erro": "corpo não é JSON válido"})
    conversation_id, resposta_erro = _conversation_id_ou_400(dados)
    if resposta_erro is not None:
        return resposta_erro
    indice = dados.get("indice")
    direcao = dados.get("direcao")
    texto = dados.get("texto")
    if not isinstance(indice, int) or direcao not in ("pergunta", "resposta") or not isinstance(texto, str):
        return _json("400 Bad Request", {"erro": "indice (int), direcao ('pergunta'|'resposta') e texto (str) são obrigatórios"})
    repositorio_trilha = RepositorioDeTrilhaJSONL(trilha_dir / f"trilha_{conversation_id}.jsonl")
    trilha = ServicoDeTrilha(repositorio_trilha)
    if direcao == "pergunta":
        registrar_pergunta_de_coleta(trilha, conversation_id, indice, texto, origem_do_texto="chat_guiado")
    else:
        registrar_resposta_de_coleta(trilha, conversation_id, indice, texto)
    return _json("200 OK", {"ok": True})


