# ── chat guiado: instrumentação das 9 perguntas de coleta (issue #51, parte 2) ─────────────


def test_chat_mensagem_pergunta_e_resposta_gravam_na_trilha_com_id(tmp_path):
    trilha_dir = tmp_path / "trilha"
    app = _criar_app(tmp_path=tmp_path, trilha_dir=trilha_dir)

    status, _, _ = _chamar(app, "POST", "/api/chat/mensagem", {
        "conversation_id": "conv-mensagem", "indice": 0, "direcao": "pergunta", "texto": "Qual sua idade?",
    })
    assert status == "200 OK"
    status, _, _ = _chamar(app, "POST", "/api/chat/mensagem", {
        "conversation_id": "conv-mensagem", "indice": 0, "direcao": "resposta", "texto": "35",
    })
    assert status == "200 OK"

    repositorio_trilha = RepositorioDeTrilhaJSONL(trilha_dir / "trilha_conv-mensagem.jsonl")
    eventos = repositorio_trilha.eventos_da_conversa("conv-mensagem")
    assert len(eventos) == 2
    enviada, recebida = eventos
    assert enviada["evento"] == "mensagem_enviada"
    assert enviada["id"]
    assert enviada["texto"] == "Qual sua idade?"
    assert recebida["evento"] == "mensagem_recebida"
    assert recebida["id"]
    assert recebida["texto"] == "35"


def test_chat_mensagem_marcador_do_lado_do_cliente_nunca_e_desfeito(tmp_path):
    """O backend só grava o que recebeu — a decisão de marcar (`[REDIGIDO]`) é 100% do cliente,
    para nome/whatsapp/email; nunca tenta reconstituir ou adivinhar o valor real."""
    trilha_dir = tmp_path / "trilha"
    app = _criar_app(tmp_path=tmp_path, trilha_dir=trilha_dir)

    status, _, _ = _chamar(app, "POST", "/api/chat/mensagem", {
        "conversation_id": "conv-marcador", "indice": 0, "direcao": "resposta", "texto": "[REDIGIDO]",
    })
    assert status == "200 OK"

    repositorio_trilha = RepositorioDeTrilhaJSONL(trilha_dir / "trilha_conv-marcador.jsonl")
    eventos = repositorio_trilha.eventos_da_conversa("conv-marcador")
    assert len(eventos) == 1
    assert eventos[0]["texto"] == "[REDIGIDO]"


def test_chat_mensagem_sem_conversation_id_e_400(app):
    status, _, _ = _chamar(app, "POST", "/api/chat/mensagem", {
        "indice": 0, "direcao": "pergunta", "texto": "Qual sua idade?",
    })
    assert status == "400 Bad Request"


def test_chat_mensagem_com_indice_ou_direcao_invalidos_e_400(app):
    status, _, _ = _chamar(app, "POST", "/api/chat/mensagem", {
        "conversation_id": "conv-invalido", "indice": "zero", "direcao": "pergunta", "texto": "x",
    })
    assert status == "400 Bad Request"

    status, _, _ = _chamar(app, "POST", "/api/chat/mensagem", {
        "conversation_id": "conv-invalido", "indice": 0, "direcao": "outra", "texto": "x",
    })
    assert status == "400 Bad Request"


