572	    mensagemBot("Seus dados são usados só para esta cotação e para um corretor falar com você, conforme a LGPD.", { cls: "sistema" });
573	    PASSOS.nome();
574	  });
575	
576	  // Lista de países (libphonenumber, gerada por scripts/gerar-paises-whatsapp.mjs — ver
577	  // docs/design/paises.json): buscada uma vez, com fallback só-Brasil se o fetch falhar.
578	  fetch("/docs/design/paises.json")
579	    .then((r) => r.json())
580	    .then((j) => { if (Array.isArray(j.paises) && j.paises.length) paises = j.paises; })
581	    .catch(() => {});
582	})();
583	</script>
