179	  function mostrarDoca({ placeholder = "", tipo = "text", botoes = [], textoLivre = true, dica = "", pais = false }) {
180	    doca.hidden = false;
181	    limparDoca();
182	    botoes.forEach((b) => {
183	      const x = el("button", "rapida" + (b.primaria ? " primaria" : ""), b.rotulo);
184	      x.type = "button"; x.onclick = () => b.acao();
185	      rapidas.append(x);
