198	
199	  function progresso(n) {
200	    $("passo-txt").textContent = n > 9 ? "Tudo pronto" : `Pergunta ${n} de 9`;
201	    $("barra").style.width = Math.min(n - 1, 9) / 9 * 100 + "%";
202	  }
