204	  // ── contato: salvo assim que nome+WhatsApp existem, atualizado quando o e-mail chega — nunca
205	  // espera o fim do fluxo (o corretor pode precisar do contato mesmo se o lead abandonar antes do
206	  // preço). Nome/WhatsApp/e-mail NUNCA entram no payload de /api/chat/cotar (ver cotar(), abaixo).
207	  async function salvarContato() {
208	    if (!dados.nome || !dados.whatsappExibicao) return;
209	    try {
210	      await fetch("/api/chat/contato", {
211	        method: "POST",
212	        headers: { "Content-Type": "application/json" },
213	        body: JSON.stringify({
214	          conversation_id: conversationId,
215	          nome: dados.nome,
216	          whatsapp: dados.whatsappExibicao,
217	          email: dados.email || null,
218	        }),
219	      });
220	    } catch (e) {
221	      // Falha ao salvar contato não pode travar a cotação em andamento — o corretor perde o
222	      // registro deste lead, mas o lead continua a conversa (e o texto de preço, quando existir,
223	      // segue vindo só da /quote via /api/chat/cotar).
224	    }
225	  }
226	
227	  // ── os passos, um por vez, na ordem da issue #46 (B.3) ──────────────────────────
228	  const PASSOS = {
229	    nome() {
230	      progresso(1);
231	      mensagemBot("Para começar, <b>qual é o seu nome completo?</b>");
232	      perguntar("Para começar, qual é o seu nome completo?");
233	      mostrarDoca({ placeholder: "Nome completo", dica: "Usamos seu nome para o corretor falar com você." });
234	      passoAtual = (v) => {
235	        const nome = v.trim();
