237	        if (partesValidas.length < 2) return erro("Digite nome e sobrenome.");
238	        mensagemLead(nome); responder(nome, true); dados.nome = nome; seguir("whatsapp");
239	      };
240	    },
241	    whatsapp() {
242	      progresso(2);
243	      mensagemBot("Qual o seu <b>WhatsApp</b>? Escolha o país e digite o número.");
244	      perguntar("Qual o seu WhatsApp? Escolha o país e digite o número.");
245	      mostrarDoca({ placeholder: "Número, com DDD", pais: true });
246	      paisSel.innerHTML = "";
247	      paises.forEach((p) => {
248	        const o = document.createElement("option");
249	        o.value = p.iso; o.textContent = `${p.bandeira} ${p.nome} +${p.ddi}`;
250	        if (p.iso === "BR") o.selected = true;
251	        paisSel.append(o);
252	      });
253	      const paisAtual = () => paises.find((p) => p.iso === paisSel.value) || paises[0];
254	      const aplicarMascaraBR = () => {
255	        const d = entrada.value.replace(/\D/g, "").slice(0, 11);
256	        if (d.length > 6) entrada.value = `(${d.slice(0, 2)}) ${d.slice(2, d.length > 10 ? 7 : 6)}-${d.slice(d.length > 10 ? 7 : 6)}`;
257	        else if (d.length > 2) entrada.value = `(${d.slice(0, 2)}) ${d.slice(2)}`;
258	        else entrada.value = d;
259	      };
260	      const aplicarMascaraOutro = () => { entrada.value = entrada.value.replace(/\D/g, "").slice(0, 14); };
261	      const atualizarTextos = () => {
262	        const p = paisAtual();
263	        // Textos EXATOS da issue #46: Brasil "Número, com DDD"; outros "Número de telefone, sem o
264	        // código do país" — nunca redigitados fora deste ponto único.
265	        if (p.iso === "BR") { entrada.placeholder = "Número, com DDD"; ajuda.textContent = "Ex.: (11) [REDIGIDO]8"; }
266	        else { entrada.placeholder = "Número de telefone, sem o código do país"; ajuda.textContent = `Só os números. O código +${p.ddi} já está no país escolhido.`; }
267	      };
268	      paisSel.onchange = () => { entrada.value = ""; entrada.oninput = paisSel.value === "BR" ? aplicarMascaraBR : aplicarMascaraOutro; atualizarTextos(); };
269	      entrada.oninput = aplicarMascaraBR;
270	      atualizarTextos();
271	      passoAtual = (v) => {
272	        const p = paisAtual();
273	        const digitos = v.replace(/\D/g, "");
274	        let exibicao;
275	        if (p.iso === "BR") {
276	          if (digitos.length !== 10 && digitos.length !== 11) return erro("Digite DDD e número, ex.: (11) [REDIGIDO]8.");
277	          const ddd = digitos.slice(0, 2), resto = digitos.slice(2);
278	          exibicao = `+${p.ddi} (${ddd}) ${digitos.length === 11 ? resto.slice(0, 5) + "-" + resto.slice(5) : resto.slice(0, 4) + "-" + resto.slice(4)}`;
279	        } else {
280	          if (digitos.length < 4 || digitos.length > 14) return erro("Digite só os números do telefone, sem o código do país.");
281	          exibicao = `+${p.ddi} ${digitos}`;
282	        }
283	        mensagemLead(exibicao);
284	        responder(exibicao, true);
285	        dados.whatsappExibicao = exibicao;
286	        salvarContato();
287	        seguir("email");
288	      };
289	    },
290	    email() {
291	      progresso(3);
292	      mensagemBot("Se quiser, deixe seu <b>e-mail</b>. É opcional.");
293	      mostrarDoca({
294	        placeholder: "[REDIGIDO]", tipo: "email",
295	        botoes: [{ rotulo: "Pular", acao: () => { mensagemLead("Prefiro não informar"); dados.email = null; salvarContato(); seguir("idade"); } }],
296	      });
297	      passoAtual = (v) => {
298	        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())) return erro("Esse e-mail não parece válido. Confira ou toque em Pular.");
299	        mensagemLead(v.trim()); dados.email = v.trim(); salvarContato(); seguir("idade");
300	      };
301	    },
302	    idade() {
303	      progresso(4);
304	      mensagemBot("E <b>quantos anos você tem?</b>");
305	      mostrarDoca({ placeholder: "Sua idade, ex.: 35", tipo: "number", dica: "Usamos a idade para a faixa de preço." });
306	      passoAtual = (v) => {
307	        const n = parseInt(v, 10);
308	        if (!Number.isInteger(n) || n <= 0) return erro("Digite só o número, ex.: 35.");
309	        mensagemLead(`${n} anos`); dados.idade = n;
310	        // Menor de 18: mensagem exata da issue #46, sem tentativa de cotação — decisão de
311	        // política que é só do frontend guiado (nunca chega a chamar /api/chat/cotar).
312	        if (n < 18) return menorDeIdade();
313	        seguir("modelo");
314	      };
315	    },
316	    modelo() {
317	      progresso(5);
318	      mensagemBot("Qual o <b>modelo</b> do seu carro? (ex.: Onix, HB20, Corolla)");
319	      mostrarDoca({ placeholder: "Modelo do carro", dica: "O modelo fica registrado para o corretor; nesta cotação não altera o preço." });
320	      passoAtual = (v) => {
321	        const modelo = v.trim();
322	        if (modelo.length < 2) return erro("Digite o modelo do carro.");
323	        mensagemLead(modelo); dados.veiculo_modelo = modelo; seguir("ano");
324	      };
325	    },
326	    ano() {
327	      progresso(6);
328	      const anoAtual = new Date().getFullYear();
329	      mensagemBot(`E o seu ${esc(dados.veiculo_modelo)}, <b>de que ano é?</b>`);
330	      const anos = [0, 1, 2, 3, 4].map((i) => anoAtual - i);
331	      mostrarDoca({
332	        placeholder: "Ou digite o ano, ex.: 2019", tipo: "number",
333	        botoes: anos.map((a) => ({ rotulo: String(a), acao: () => passoAtual(String(a)) })),
334	        dica: "Carros com até 20 anos de uso são aceitos.",
335	      });
336	      passoAtual = (v) => {
337	        const n = parseInt(v, 10);
338	        if (!Number.isInteger(n) || n < 1950 || n > anoAtual + 1) return erro(`Digite um ano entre 1950 e ${anoAtual + 1}.`);
339	        mensagemLead(String(n)); dados.veiculo_ano = n; seguir("cep");
340	      };
341	    },
342	    cep() {
343	      progresso(7);
344	      // Decisão do dono (13/09/2026, comentário na #46): CEP fica OBRIGATÓRIO, sem botão de
345	      // pular — sem ele a /quote cobra até 30% a menos, em silêncio, pra carro que dorme em
346	      // região de risco (regra já existente em dominio/validacao.py, achado da Fase B do PR 2).
347	      mensagemBot("Qual o <b>CEP</b> onde o carro fica à noite?");
348	      mostrarDoca({
349	        placeholder: "[REDIGIDO]",
350	        dica: "O CEP entra só no cálculo e fica mascarado no nosso registro.",
351	      });
352	      entrada.oninput = () => { let d = entrada.value.replace(/\D/g, "").slice(0, 8); entrada.value = d.length > 5 ? d.slice(0, 5) + "-" + d.slice(5) : d; };
353	      passoAtual = (v) => {
354	        if (!/^\d{5}-\d{3}$/.test(v)) return erro("CEP com 8 números, ex.: [REDIGIDO].");
355	        mensagemLead(v); dados.cep = v; seguir("plano");
356	      };
357	    },
358	    async plano() {
359	      progresso(8);
360	      // Coberturas e franquia vêm SEMPRE de GET /api/planos (proxy de infra.planos_http) — nunca
361	      // escritas à mão aqui (issue #46, B.3.8).
362	      const resposta = await fetch("/api/planos");
363	      if (!resposta.ok) {
364	        mensagemBot("Não consegui carregar os planos agora. Toque para tentar de novo.", { cls: "sistema" });
365	        mostrarDoca({ textoLivre: false, botoes: [{ rotulo: "Tentar de novo", primaria: true, acao: () => PASSOS.plano() }] });
366	        return;
367	      }
368	      const catalogo = await resposta.json();
369	      const planos = catalogo.planos || [];
370	      const moeda = catalogo.moeda || "BRL";
371	      mensagemBot(
372	        'Agora escolha o <b>plano</b>. Toque no card que faz mais sentido para você:' +
373	        '<details><summary>O que é franquia?</summary>Franquia é o valor que você paga do seu bolso ' +
374	        'quando usa o seguro para consertar o carro depois de um dano parcial, como uma batida. O ' +
375	        'seguro paga o restante do conserto. Exemplo ilustrativo: com franquia de R$ 3.000,00, um ' +
376	        'conserto de R$ 8.000,00 fica R$ 3.000,00 para você e R$ 5.000,00 para o seguro. Quanto ' +
377	        'menor a franquia, menos você paga quando precisa usar o seguro.</details>'
378	      );
379	      const grade = el("div", "planos");
380	      planos.forEach((p) => {
381	        const franquia = Number(p.franquia || 0).toLocaleString("pt-BR", { style: "currency", currency: moeda });
382	        const coberturas = (p.coberturas || []).map((c) => `<li>${esc(c)}</li>`).join("");
383	        const card = el("button", "plano");
384	        card.type = "button"; card.setAttribute("aria-pressed", "false");
385	        card.innerHTML = `<h4>${esc(p.nome || p.id)}</h4><div class="franquia">Franquia <b>${franquia}</b></div><ul>${coberturas}</ul>`;
386	        card.onclick = () => {
387	          grade.querySelectorAll(".plano").forEach((c) => { c.setAttribute("aria-pressed", "false"); c.disabled = true; });
388	          card.setAttribute("aria-pressed", "true");
389	          mensagemLead(`Plano ${p.nome || p.id}`);
390	          dados.plano_id = p.id; dados.planoNome = p.nome || p.id;
391	          seguir("inicio");
392	        };
393	        grade.append(card);
394	      });
395	      anexar(grade);
396	      mostrarDoca({ textoLivre: false, dica: "O preço de cada plano depende do seu perfil. Ele aparece depois do resumo." });
397	    },
398	    inicio() {
399	      progresso(9);
400	      mensagemBot("Por último: <b>quando o seguro deve começar?</b>");
401	      const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
402	      const proximoMes = new Date(hoje.getFullYear(), hoje.getMonth() + 1, 1);
403	      const dataBR = (d) => d.toLocaleDateString("pt-BR");
404	      mostrarDoca({
405	        tipo: "date",
406	        botoes: [
407	          { rotulo: `Hoje (${dataBR(hoje)})`, acao: () => escolherInicio(hoje) },
408	          { rotulo: `1º do próximo mês (${dataBR(proximoMes)})`, acao: () => escolherInicio(proximoMes) },
409	        ],
410	        dica: "Ou escolha outra data no campo acima.",
411	      });
412	      entrada.min = hoje.toISOString().slice(0, 10);
413	      passoAtual = (v) => {
414	        if (!v) return erro("Escolha uma data.");
415	        const [a, m, d] = v.split("-").map(Number);
416	        escolherInicio(new Date(a, m - 1, d));
417	      };
418	    },
419	    resumo() {
420	      progresso(10);
421	      mensagemBot("Confere se está tudo certo:");
422	      // `new Date("2026-09-13")` (string SEM hora) é interpretado como meia-noite UTC — num
423	      // fuso atrás de UTC (Brasil, UTC-3) isso vira "12/09/2026" na tela, um dia a menos do que
424	      // foi escolhido (achado ao vivo no Browser desta sessão, PR 2 issue #46). Construindo a
425	      // partir dos componentes ano/mês/dia (fuso LOCAL, igual ao construtor já usado em
426	      // escolherInicio/passoAtual do CEP) evita o parse como UTC.
427	      const dataBR = (iso) => { const [a, m, d] = iso.split("-").map(Number); return new Date(a, m - 1, d).toLocaleDateString("pt-BR"); };
428	      const linha = (rot, val, passo) => `<dt>${esc(rot)}</dt><dd>${esc(val)}</dd><dd><button class="alt" type="button" data-passo="${passo}">alterar</button></dd>`;
429	      const c = el("div", "cartao-resumo");
430	      c.innerHTML = `<dl>
431	        ${linha("Nome", dados.nome, "nome")}
432	        ${linha("WhatsApp", dados.whatsappExibicao, "whatsapp")}
433	        ${linha("E-mail", dados.email || "não informado", "email")}
434	        ${linha("Idade", dados.idade + " anos", "idade")}
435	        ${linha("Carro", dados.veiculo_modelo + " " + dados.veiculo_ano, "modelo")}
436	        ${linha("CEP", dados.cep || "não informado", "cep")}
437	        ${linha("Plano", dados.planoNome, "plano")}
438	        ${linha("Início", dataBR(dados.data_inicio), "inicio")}
